const isDark = async () => {
  const sunset = await Entity.get('Weather', 'sunset');
  const sunrise = await Entity.get('Weather', 'sunrise');
  const now = new Date();
  return now > new Date(sunset) || now < new Date(sunrise);
};

const lamps = await Entity.filter({type: 'lamp'});
for (const lamp of lamps) {
  if (lamp.name === 'Garden lamp') continue;
  await Entity.set(lamp.name, 'state', 'off');
}

if (!(await isDark())) {
  await Entity.set('Garden lamp', 'state', 'off');
}

